if (root == nullptr) {
    return;
}

// Standard BST delete
if (item < root->data) {
    avlDelete(root->left, item);
} else if (item > root->data) {
    avlDelete(root->right, item);
} else {
    // Node with only one child or no child
    if (root->left == nullptr || root->right == nullptr) {
        TreeNode* temp = root->left ? root->left : root->right;

        // No child case
        if (temp == nullptr) {
            temp = root;
            root = nullptr;
        } else { // One child case
            *root = *temp; // Copy the contents of the non-empty child
        }
        delete temp;
    } else {
        // Node with two children: get inorder successor (smallest in right subtree)
        TreeNode* temp = bstFindMin(root->right);

        // Copy the inorder successor's data to this node
        root->data = temp->data;

        // Delete the inorder successor
        avlDelete(root->right, temp->data);
    }
}

// If the tree had only one node then return
if (root == nullptr) {
    return;
}

// Update height of the current node
root->height = 1 + std::max(bstHeight(root->left), bstHeight(root->right));

// Get the balance factor
int balance = bstHeight(root->left) - bstHeight(root->right);

// If unbalanced, there are 4 cases

// Left Left Case
if (balance > 1 && bstHeight(root->left->left) >= bstHeight(root->left->right)) {
    avlRotateRight(root);
    return;
}

// Left Right Case
if (balance > 1 && bstHeight(root->left->left) < bstHeight(root->left->right)) {
    avlRotateLeft(root->left);
    avlRotateRight(root);
    return;
}

// Right Right Case
if (balance < -1 && bstHeight(root->right->right) >= bstHeight(root->right->left)) {
    avlRotateLeft(root);
    return;
}

// Right Left Case
if (balance < -1 && bstHeight(root->right->right) < bstHeight(root->right->left)) {
    avlRotateRight(root->right);
    avlRotateLeft(root);
}

